51	@RestController
52	@CrossOrigin(exposedHeaders = "errors, content-type")
53	@RequestMapping("/api")
54	public class OwnerRestControllerV1 implements OwnersApi {
55	
56	    private final ClinicService clinicService;
57	
58	    private final OwnerMapper ownerMapper;
59	
60	    private final PetMapper petMapper;
61	
62	    private final VisitMapper visitMapper;
63	
64	    public OwnerRestControllerV1(ClinicService clinicService,
65	                                 OwnerMapper ownerMapper,
66	                                 PetMapper petMapper,
67	                                 VisitMapper visitMapper) {
68	        this.clinicService = clinicService;
69	        this.ownerMapper = ownerMapper;
70	        this.petMapper = petMapper;
71	        this.visitMapper = visitMapper;
72	    }
73	
74	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
75	    @Override
76	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
77	        Collection<Owner> owners;
78	        if (lastName != null) {
79	            owners = this.clinicService.findOwnerByLastName(lastName);
80	        } else {
81	            owners = this.clinicService.findAllOwners();
82	        }
83	        if (owners.isEmpty()) {
84	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
85	        }
86	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
87	    }
88	
89	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
90	    @Override
91	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
92	        Owner owner = this.clinicService.findOwnerById(ownerId);
93	        if (owner == null) {
94	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
95	        }
96	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
97	    }
98	
99	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
100	    @Override
101	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
102	        HttpHeaders headers = new HttpHeaders();
103	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
104	        Collection<Owner> owners = this.clinicService.findAllOwners();
105	        owner.setRegistrationDate(BusinessDays.effective(owner));
106	        if (owners.stream()
107	            .filter(o -> owner.getRegistrationDate().equals(o.getRegistrationDate())).count() >= 100) {
108	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
109	        }
110	        if (Identities.isDuplicate(owners, owner)) {
111	            return new ResponseEntity<>(HttpStatus.CONFLICT);
112	        }
113	        if (CityCodes.countInCity(owners, owner) >= 50) {
114	            return new ResponseEntity<>(HttpStatus.CONFLICT);
115	        }
116	        Households.joinHousehold(owners, owner, ownerFieldsDto.getSharesHousehold())
117	            .forEach(this.clinicService::saveOwner);
118	        owner.assignCustomerCode(CityCodes.countInCity(owners, owner));
119	        owner.setNamesakeCount(Namesakes.count(owners, owner));
120	        owner.setBulkSignupWarning(BulkSignups.exceededDailyLimit(owners, owner));
121	        this.clinicService.saveOwner(owner);
122	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
123	        headers.setLocation(UriComponentsBuilder.newInstance()
124	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
125	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
126	    }
127	
128	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
129	    @Override
130	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
131	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
132	        if (currentOwner == null) {
133	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
134	        }
135	        currentOwner.setAddress(ownerFieldsDto.getAddress());
136	        currentOwner.setCity(ownerFieldsDto.getCity());
137	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
138	        currentOwner.setLastName(ownerFieldsDto.getLastName());
139	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
140	        this.clinicService.saveOwner(currentOwner);
141	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
142	    }
143	
144	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
145	    @Transactional
146	    @Override
147	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
148	        Owner owner = this.clinicService.findOwnerById(ownerId);
149	        if (owner == null) {
150	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
151	        }
152	        this.clinicService.deleteOwner(owner);
153	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
154	    }
155	
156	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
157	    @Override
158	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
159	        Owner owner = this.clinicService.findOwnerById(ownerId);
160	        if (owner == null) {
161	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
162	        }
163	        HttpHeaders headers = new HttpHeaders();
164	        Pet pet = petMapper.toPet(petFieldsDto);
165	        owner.setId(ownerId);
166	        pet.setOwner(owner);
167	        pet.getType().setName(null);
168	        this.clinicService.savePet(pet);
169	        PetDto petDto = petMapper.toPetDto(pet);
170	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
171	            .buildAndExpand(pet.getId()).toUri());
172	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
173	    }
174	
175	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
176	    @Override
177	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
178	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
179	        if (currentOwner != null) {
180	            Pet currentPet = this.clinicService.findPetById(petId);
181	            if (currentPet != null) {
182	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
183	                currentPet.setName(petFieldsDto.getName());
184	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
185	                this.clinicService.savePet(currentPet);
186	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
187	            }
188	        }
189	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
190	    }
191	
192	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
193	    @Override
194	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
195	        HttpHeaders headers = new HttpHeaders();
196	        Visit visit = visitMapper.toVisit(visitFieldsDto);
197	        Pet pet = new Pet();
198	        pet.setId(petId);
199	        visit.setPet(pet);
200	        this.clinicService.saveVisit(visit);
201	        VisitDto visitDto = visitMapper.toVisitDto(visit);
202	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
203	            .buildAndExpand(visit.getId()).toUri());
204	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
205	    }
206	
207	
208	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
209	    @Override
210	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
211	        Owner owner = this.clinicService.findOwnerById(ownerId);
212	        if (owner != null) {
213	            Pet pet = owner.getPet(petId);
214	            if (pet != null) {
215	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
216	            }
217	        }
218	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
219	    }
220	}
