11	final class CityCodes {
12	
13	    private CityCodes() {
14	    }
15	
16	    /** How many existing owners share {@code candidate}'s city. */
17	    static int countInCity(Collection<Owner> existing, Owner candidate) {
18	        return (int) existing.stream().filter(other -> sameCity(other, candidate)).count();
