7	/**
8	 * Bulk-signup rule for owners: a create is flagged once more than 80 owners have
9	 * already been created on the candidate's registration date.
10	 */
11	final class BulkSignups {
12	
13	    private BulkSignups() {
14	    }
15	
16	    /** Whether more than 80 existing owners share {@code candidate}'s registration date. */
17	    static boolean exceededDailyLimit(Collection<Owner> existing, Owner candidate) {
18	        return existing.stream()
19	            .filter(other -> candidate.getRegistrationDate().equals(other.getRegistrationDate()))
20	            .count() > 80;
