8	/**
9	 * Email-uniqueness rule for owners: an owner's email must be unique across all
10	 * owners when compared case-insensitively. Owners without an email never clash.
11	 */
12	final class Emails {
13	
14	    private Emails() {
15	    }
16	
17	    /** Whether {@code candidate}'s email is already used by an existing owner. */
18	    static boolean isDuplicate(Collection<Owner> existing, Owner candidate) {
