3	/**
4	 * Derives an owner's numeric membership level: starts at 1, plus 1 when an
5	 * email is present and plus 1 when namesakeCount is 0, capped at 3. Level 4 is
6	 * reserved for tenure.
7	 */
8	public final class MembershipLevels {
9	
10	    private MembershipLevels() {
11	    }
12	
13	    /** Membership level (1 to 3) for {@code owner}. */
14	    public static int levelOf(Owner owner) {
15	        int level = 1;
16	        if (owner.getEmail() != null) {
17	            level++;
18	        }
19	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
20	            level++;
21	        }
22	        return Math.min(level, 3);
23	    }
24	}
