1	package org.springframework.samples.petclinic.rest.validation;
2	
3	import java.util.Map;
4	
5	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
6	
7	import jakarta.validation.ConstraintValidator;
8	import jakarta.validation.ConstraintValidatorContext;
9	
10	/**
11	 * Validates an owner's optional postcode against its city's region: a 4-digit
12	 * postcode must fall in the region's inclusive range (NSW 2000-2099,
13	 * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any
14	 * 4-digit postcode. An absent or non-4-digit value passes here - absence is
15	 * allowed and the 4-digit format is enforced separately by the field pattern.
16	 */
17	public class PostcodeValidator implements ConstraintValidator<PostcodeValidation, OwnerFieldsDto> {
18	
19	    private static final Map<String, int[]> CITY_RANGE = Map.of(
20	        "Sydney", new int[] {2000, 2099},
21	        "Melbourne", new int[] {3000, 3099},
22	        "Brisbane", new int[] {4000, 4099});
23	
24	    @Override
25	    public boolean isValid(OwnerFieldsDto owner, ConstraintValidatorContext context) {
26	        String postcode = owner.getPostcode();
27	        if (postcode == null || !postcode.matches("\\d{4}")) {
28	            return true;
29	        }
30	        int[] range = CITY_RANGE.get(owner.getCity());
31	        if (range == null) {
32	            return true;
33	        }
34	        int value = Integer.parseInt(postcode);
35	        return value >= range[0] && value <= range[1];
36	    }
37	}
